production_rows = sql_data.get('Production', [])
scrap_rows = sql_data.get('Scrap', [])
net_production = []

if not production_rows:
    out('net_production').append({'machine': None, 'net_qty': 0})
else:
    prod_by_machine = {}
    for row in production_rows:
        m = row.get('machine')
        q = row.get('qty', 0)
        if m is None:
            continue
        prod_by_machine[m] = prod_by_machine.get(m, 0) + (q or 0)

    scrap_by_machine = {}
    for row in scrap_rows:
        m = row.get('machine')
        q = row.get('qty', 0)
        if m is None:
            continue
        scrap_by_machine[m] = scrap_by_machine.get(m, 0) + (q or 0)

    for m, prod in prod_by_machine.items():
        scrap = scrap_by_machine.get(m, 0)
        net = prod - scrap
        net_production.append({'machine': m, 'net_qty': net})
